from pathlib import Path
from hashlib import sha256

def obj(t,b):return sha256(t.encode()+b' '+str(len(b)).encode()+b'\0'+b).digest()
def tree(p):
 es=[]
 for x in sorted(p.iterdir(),key=lambda x:x.name.encode()):
  if x.is_dir(): mode=b'40000'; h=tree(x)
  elif x.is_file(): mode=b'100755' if x.stat().st_mode&0o111 else b'100644'; h=obj('blob',x.read_bytes())
  else:continue
  es.append(mode+b' '+x.name.encode()+b'\0'+h)
 return obj('tree',b''.join(es))
for p in ['/generation-evidence/codex-trace','/candidate']:
